/** The rating badge's floor (spec v2 §5.6, D4). */
export const MINGLA_REVIEWS_MIN = 20;
/** The processes section needs this many steps (Q7). */
export const PROCESS_STEPS_MIN = 3;
/** The ticker needs this many owner phrases (Q8). */
export const TICKER_PHRASES_MIN = 2;

const yes: SectionEligibility = { eligible: true, reason: null };
const no = (reason: SectionReason): SectionEligibility => ({ eligible: false, reason });
const n = (value: number | undefined): number => (typeof value === "number" && Number.isFinite(value) ? value : 0);
const anyOf = (counts: OfferingCounts): number => n(counts.trip) + n(counts.event) + n(counts.experience);

/** Always placeable: Mingla's own words or the owner's (forms, headers, layout). */
const ALWAYS: ReadonlySet<string> = new Set(["newsletter_signup", "contact_form", "page_header", "cta", "divider", "spacer"]);
/** Ari places these only with owner material (the claim check applies); the composer never does. */
export const OWNER_MATERIAL_ONLY: ReadonlySet<string> = new Set(["stats", "team", "pull_quote", "map_embed"]);

/**
 * Whether a block of `type` may be placed for this inventory, and why not.
 * Types this table does not name are eligible (their own validators apply).
 */
export function sectionEligibility(type: string, inventory: ContentInventory, options: SectionOptions = {}): SectionEligibility {
  // Options that need their own source, checked before the block's own rule.
  if (options.show_rating === true && n(inventory.mingla_reviews) < MINGLA_REVIEWS_MIN) return no("TOO_FEW_MINGLA_REVIEWS");
  if (type === "hero" && options.fact_badge === true && n(inventory.quick_facts) < 1) return no("NO_FACTS");
  if (type === "hero" && options.booking_bar === true && inventory.booking_target !== true) return no("NO_BOOKING_TARGET");
  if (ALWAYS.has(type)) return yes;
  switch (type) {
    case "hero":
      if (options.show_search === true && n(inventory.upcoming.trip) < 2) return no("TOO_FEW_TRIPS_FOR_SEARCH");
      return inventory.has_cover || n(inventory.ready_photos) >= 1 ? yes : no("NO_PHOTO");
    case "offering_grid": {
      if (options.kind === "stay") return n(inventory.live_stay_offerings) >= 1 ? yes : no("NO_ROOMS");
      if (options.mode === "past") {
        const ended = options.kind ? n(inventory.ended[options.kind]) : anyOf(inventory.ended);
        return ended >= 1 ? yes : no("NO_PAST");
      }
      const upcoming = options.kind ? n(inventory.upcoming[options.kind]) : anyOf(inventory.upcoming);
      return upcoming >= 1 ? yes : no("NO_UPCOMING");
    }
    case "offering_history":
      return anyOf(inventory.ended) >= 1 ? yes : no("NO_PAST");
    case "testimonials":
      if (options.has_typed_items === true || options.from_collection === false) return no("REVIEWS_ONLY_FROM_COLLECTION");
      return n(inventory.confirmed_reviews) >= 1 ? yes : no("NO_CONFIRMED_REVIEWS");
    case "destination_grid":
      return n(inventory.enabled_destinations) >= 1 ? yes : no("NO_DESTINATIONS");
    case "story_grid":
      return n(inventory.enabled_stories) >= 1 ? yes : no("NO_STORIES");
    case "video_feature":
      return n(inventory.ready_videos) >= 1 ? yes : no("NO_VIDEO");
    case "feature_cards":
      return n(inventory.value_points) >= 2 ? yes : no("TOO_FEW_VALUE_POINTS");
    case "faq":
      return n(inventory.faq_items) >= 1 ? yes : no("NO_FAQ");
    case "gallery":
      return n(inventory.ready_photos) >= (options.layout === "pinned" ? 4 : 3) ? yes : no("NO_PHOTOS");
    case "media_feature":
      return n(inventory.ready_photos) >= 1 ? yes : no("NO_PHOTOS");
    case "rich_text":
      return options.page !== "about" || inventory.has_bio ? yes : no("NO_TEXT");
    case "contact_details":
      return inventory.has_contact_email || inventory.has_city ? yes : no("NO_CONTACT");
    case "process_steps":
      return n(inventory.process_steps) >= PROCESS_STEPS_MIN ? yes : no("NO_PROCESS_STEPS");
    case "marquee":
      return n(inventory.ticker_phrases) >= TICKER_PHRASES_MIN ? yes : no("NO_PHRASES");
    case "venue_reservation":
      return n(inventory.verified_venues) === 1 && inventory.venue_reservations_on === true ? yes : no("NO_VERIFIED_VENUE");
    case "menu_board":
      return n(inventory.verified_venues) >= 1 && inventory.published_menu === true ? yes : no("NO_MENU");
    case "ticket_tiers":
      return n(inventory.public_ticket_tiers) >= 1 ? yes : no("NO_TICKET_TIERS");
    case "availability":
      if (options.source === "venue_slots") {
        if (n(inventory.verified_venues) !== 1 || inventory.venue_reservations_on !== true) return no("NO_VERIFIED_VENUE");
        return n(inventory.open_venue_slots) >= 1 ? yes : no("NO_LIVE_SLOTS");
      }
      if (options.source === "stay_nights") {
        return n(inventory.live_stay_offerings) >= 1 && n(inventory.sellable_nights) >= 1 ? yes : no("NO_LIVE_NIGHTS");
      }
      return n(inventory.bookable_dates) >= 1 ? yes : no("NO_LIVE_DATES");
    default:
      return yes;
  }
}

